<?php
use App\Models\Product;use App\Models\ProductionQualityPlan;use App\Models\ProductionQualityPlanCheck;use App\Models\Unit;use App\Support\CompanyFeatures;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
use function Livewire\Volt\{layout,mount,state};
layout('layouts.app');
state(['plan'=>null,'product_id'=>'','name'=>'','code'=>'','version'=>'','inspection_stage'=>'production_completion','requires_approval'=>true,'effective_from'=>'','effective_to'=>'','notes'=>'','checks'=>[]]);
mount(function(?ProductionQualityPlan $plan=null){abort_unless(CompanyFeatures::manufacturingEnabled()&&auth()->user()?->can('production.manage_quality_plans'),403);if($plan?->exists){abort_unless($plan->status==='draft',403);$plan->load('checks');$this->plan=$plan;$this->fill($plan->only(['product_id','name','code','version','inspection_stage','requires_approval','notes']));$this->effective_from=$plan->effective_from?->format('Y-m-d')??'';$this->effective_to=$plan->effective_to?->format('Y-m-d')??'';$this->checks=$plan->checks->map(fn($c)=>[...$c->only(['id','name','description','check_type','unit_id','minimum_value','maximum_value','target_value','allowed_options','required','critical','acceptance_rule','sort_order','notes']),'key'=>'saved-'.$c->id,'allowed_options_text'=>implode(', ',$c->allowed_options??[])])->all();}if(!$this->checks)$this->addCheck();});
$addCheck=function(){$this->checks[]=['key'=>(string)str()->uuid(),'name'=>'','description'=>'','check_type'=>'numeric','unit_id'=>'','minimum_value'=>'','maximum_value'=>'','target_value'=>'','allowed_options_text'=>'','required'=>true,'critical'=>false,'acceptance_rule'=>'within_range','sort_order'=>count($this->checks)+1,'notes'=>''];};
$removeCheck=function(int $i){unset($this->checks[$i]);$this->checks=array_values($this->checks);};
$save=function(){
 $data=$this->validate(['product_id'=>['required',Rule::exists('products','id')->where(fn($q)=>$q->where('company_id',CompanyFeatures::companyId())->where('inventory_source','manufactured'))],'name'=>['required','string','max:255'],'code'=>['nullable','string','max:60'],'version'=>['nullable','string','max:50'],'inspection_stage'=>['required',Rule::in(ProductionQualityPlan::STAGES)],'requires_approval'=>['boolean'],'effective_from'=>['nullable','date'],'effective_to'=>['nullable','date','after_or_equal:effective_from'],'notes'=>['nullable','string','max:5000'],'checks'=>['required','array','min:1'],'checks.*.name'=>['required','string','max:255'],'checks.*.check_type'=>['required',Rule::in(ProductionQualityPlanCheck::TYPES)],'checks.*.acceptance_rule'=>['required',Rule::in(ProductionQualityPlanCheck::RULES)],'checks.*.unit_id'=>['nullable','exists:units,id'],'checks.*.minimum_value'=>['nullable','numeric'],'checks.*.maximum_value'=>['nullable','numeric'],'checks.*.target_value'=>['nullable','numeric'],'checks.*.required'=>['boolean'],'checks.*.critical'=>['boolean'],'checks.*.sort_order'=>['nullable','integer','min:0'],'checks.*.notes'=>['nullable','string','max:5000']]);
 DB::transaction(function()use($data){$attrs=[...collect($data)->except('checks')->all(),'company_id'=>CompanyFeatures::companyId(),'status'=>'draft','created_by'=>$this->plan?->created_by?:auth()->id(),'updated_by'=>auth()->id()];$plan=$this->plan;if($plan)$plan->update($attrs);else $plan=ProductionQualityPlan::query()->create($attrs);$plan->checks()->delete();foreach($data['checks'] as $i=>$check){$raw=$this->checks[$i];$plan->checks()->create([...$check,'company_id'=>$plan->company_id,'unit_id'=>$check['unit_id']?:null,'minimum_value'=>$check['minimum_value']!==''?$check['minimum_value']:null,'maximum_value'=>$check['maximum_value']!==''?$check['maximum_value']:null,'target_value'=>$check['target_value']!==''?$check['target_value']:null,'allowed_options'=>collect(explode(',',$raw['allowed_options_text']??''))->map(fn($v)=>trim($v))->filter()->values()->all()?:null,'description'=>$raw['description']??null]);}$this->plan=$plan;});session()->flash('success','Draft quality plan saved.');$this->redirectRoute('production.quality.plans.show',$this->plan,navigate:true);
};
?>
<div><x-page-header :title="$plan?'Edit Quality Plan':'Create Quality Plan'" description="Draft plans remain editable until activation." :breadcrumbs="[__('production.quality.plans')=>route('production.quality.plans.index'),$plan?'Edit':'Create'=>null]"/><form wire:submit="save" class="space-y-5"><x-card><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><label class="text-sm font-bold">Product<select wire:model="product_id" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">Select manufactured product</option>@foreach(Product::query()->manufactured()->orderBy('name')->get() as $p)<option value="{{$p->id}}">{{$p->name}}</option>@endforeach</select>@error('product_id')<span class="text-xs text-red-600">{{$message}}</span>@enderror</label><x-form-input label="Plan Name" name="name" wire:model="name" required/><x-form-input label="Code" name="code" wire:model="code"/><x-form-input label="Version" name="version" wire:model="version"/><label class="text-sm font-bold">Stage<select wire:model="inspection_stage" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950">@foreach(ProductionQualityPlan::STAGES as $v)<option value="{{$v}}">{{str($v)->headline()}}</option>@endforeach</select></label><label class="flex items-center gap-2 text-sm font-bold"><input type="checkbox" wire:model="requires_approval">Requires approval</label><x-form-input label="Effective From" name="effective_from" type="date" wire:model="effective_from"/><x-form-input label="Effective To" name="effective_to" type="date" wire:model="effective_to"/><label class="text-sm font-bold md:col-span-2">Notes<textarea wire:model="notes" class="mt-1 block min-h-20 w-full rounded-lg border-slate-200 dark:bg-navy-950"></textarea></label></div></x-card>
<x-card><div class="mb-4 flex justify-between"><h2 class="text-lg font-black">Inspection Checks</h2><button type="button" wire:click="addCheck" class="rounded-lg border px-3 py-2 text-sm font-bold">Add check</button></div><div class="space-y-4">@foreach($checks as $i=>$check)<div wire:key="qc-check-{{$check['key']}}" class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><x-form-input label="Check Name" name="checks.{{$i}}.name" wire:model="checks.{{$i}}.name" required/><label class="text-sm font-bold">Type<select wire:model.live="checks.{{$i}}.check_type" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950">@foreach(ProductionQualityPlanCheck::TYPES as $v)<option value="{{$v}}">{{str($v)->headline()}}</option>@endforeach</select></label><label class="text-sm font-bold">Acceptance Rule<select wire:model="checks.{{$i}}.acceptance_rule" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950">@foreach(ProductionQualityPlanCheck::RULES as $v)<option value="{{$v}}">{{str($v)->headline()}}</option>@endforeach</select></label><label class="text-sm font-bold">Unit<select wire:model="checks.{{$i}}.unit_id" class="mt-1 block w-full rounded-lg border-slate-200 dark:bg-navy-950"><option value="">None</option>@foreach(Unit::orderBy('name')->get() as $u)<option value="{{$u->id}}">{{$u->name}}</option>@endforeach</select></label><x-form-input label="Minimum" name="checks.{{$i}}.minimum_value" wire:model="checks.{{$i}}.minimum_value"/><x-form-input label="Maximum" name="checks.{{$i}}.maximum_value" wire:model="checks.{{$i}}.maximum_value"/><x-form-input label="Target" name="checks.{{$i}}.target_value" wire:model="checks.{{$i}}.target_value"/><x-form-input label="Options (comma separated)" name="checks.{{$i}}.allowed_options_text" wire:model="checks.{{$i}}.allowed_options_text"/><x-form-input label="Sort Order" name="checks.{{$i}}.sort_order" type="number" wire:model="checks.{{$i}}.sort_order"/><label class="flex items-center gap-2 text-sm font-bold"><input type="checkbox" wire:model="checks.{{$i}}.required">Required</label><label class="flex items-center gap-2 text-sm font-bold"><input type="checkbox" wire:model="checks.{{$i}}.critical">Critical</label><button type="button" wire:click="removeCheck({{$i}})" class="text-left text-sm font-bold text-red-600">Remove</button></div></div>@endforeach</div></x-card><div class="flex justify-end"><button class="rounded-lg bg-build-orange px-5 py-3 font-black text-white">Save Draft</button></div></form></div>
